select
  'cancel_restore' as category_for_grouping,
  names.plan_name as plan_name,
  'Cancelled' as [key],
  agg.ledger_total as [value]
from (
  select distinct plan_name
  from {plans}
  where trim(concat('', coalesce(plan_name, ''))) <> ''
) names
inner join (
  select
    lower(trim(concat('', coalesce([所属计划], '')))) as plan_key,
    sum(
      case
        when trim(concat('', coalesce(cast([数量] as string), '0'))) in ('--', '', 'null') then 0
        else cast([数量] as number)
      end
    ) as ledger_total
  from {cancel_restore}
  where wf_month_key([变更日期]) is not null
    and wf_month_key([变更日期]) <= {constants.workflowMonth}
    and trim(concat('', coalesce(cast([变更类型] as string), ''))) <> '已归属到期失效'
  group by lower(trim(concat('', coalesce([所属计划], ''))))
) agg
on (
  lower(trim(concat('', coalesce(names.plan_name, '')))) = agg.plan_key
  or lower(trim(concat('', coalesce(names.plan_name, '')))) like concat('% ', agg.plan_key)
)
